class Solution {
    public int[] threeEqualParts(int[] arr) {
        int n = arr.length;
        List<Integer> ones = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            if (arr[i] == 1) {
                ones.add(i);
            }
        }
        if (ones.isEmpty()) {
            return new int[]{0, 2};
        }
        if (ones.size() % 3 != 0) {
            return new int[]{-1, -1};
        }

        int group = ones.size() / 3;
        int trailingZeros = n - 1 - ones.get(ones.size() - 1);
        int endFirstOnes = ones.get(group - 1);
        int startSecondOnes = ones.get(group);
        int endSecondOnes = ones.get(2 * group - 1);
        int startThirdOnes = ones.get(2 * group);

        int zerosBetweenFirstAndSecond = startSecondOnes - endFirstOnes - 1;
        int zerosBetweenSecondAndThird = startThirdOnes - endSecondOnes - 1;
        if (zerosBetweenFirstAndSecond < trailingZeros
                || zerosBetweenSecondAndThird < trailingZeros) {
            return new int[]{-1, -1};
        }

        int firstCut = endFirstOnes + trailingZeros;
        int secondCut = endSecondOnes + trailingZeros + 1;
        int suffixLength = n - startThirdOnes;
        int firstStart = ones.get(0);
        int secondStart = startSecondOnes;
        for (int offset = 0; offset < suffixLength; offset++) {
            int bit = arr[firstStart + offset];
            if (arr[secondStart + offset] != bit || arr[startThirdOnes + offset] != bit) {
                return new int[]{-1, -1};
            }
        }
        return new int[]{firstCut, secondCut};
    }
}

class Solution {
    public int[] threeEqualParts(int[] arr) {
        int n = arr.length;
        int ones = 0;
        for (int bit : arr) {
            ones += bit;
        }
        if (ones == 0) {
            return new int[]{0, 2};
        }
        if (ones % 3 != 0) {
            return new int[]{-1, -1};
        }

        int group = ones / 3;
        int[] starts = new int[3];
        int seen = 0;
        for (int i = 0; i < n; i++) {
            if (arr[i] == 1) {
                seen++;
                if (seen == 1) {
                    starts[0] = i;
                } else if (seen == group + 1) {
                    starts[1] = i;
                } else if (seen == 2 * group + 1) {
                    starts[2] = i;
                }
            }
        }

        int suffixLength = n - starts[2];
        if (starts[0] + suffixLength > starts[1] || starts[1] + suffixLength > starts[2]) {
            return new int[]{-1, -1};
        }
        String target = buildBits(arr, starts[2], suffixLength);
        String first = buildBits(arr, starts[0], suffixLength);
        String second = buildBits(arr, starts[1], suffixLength);
        if (!first.equals(target) || !second.equals(target)) {
            return new int[]{-1, -1};
        }
        return new int[]{starts[0] + suffixLength - 1, starts[1] + suffixLength};
    }

    private String buildBits(int[] arr, int start, int length) {
        StringBuilder builder = new StringBuilder(length);
        for (int offset = 0; offset < length; offset++) {
            builder.append(arr[start + offset]);
        }
        return builder.toString();
    }
}

class Solution {
    private static final long BASE = 911382323L;

    public int[] threeEqualParts(int[] arr) {
        int n = arr.length;
        int ones = 0;
        for (int bit : arr) {
            ones += bit;
        }
        if (ones == 0) {
            return new int[]{0, 2};
        }
        if (ones % 3 != 0) {
            return new int[]{-1, -1};
        }

        int group = ones / 3;
        int start1 = -1;
        int start2 = -1;
        int start3 = -1;
        int seen = 0;
        for (int i = 0; i < n; i++) {
            if (arr[i] == 1) {
                seen++;
                if (seen == 1) {
                    start1 = i;
                } else if (seen == group + 1) {
                    start2 = i;
                } else if (seen == 2 * group + 1) {
                    start3 = i;
                }
            }
        }

        int suffixLength = n - start3;
        if (start1 + suffixLength > start2 || start2 + suffixLength > start3) {
            return new int[]{-1, -1};
        }

        long[] prefix = new long[n + 1];
        long[] power = new long[n + 1];
        power[0] = 1L;
        for (int i = 0; i < n; i++) {
            prefix[i + 1] = prefix[i] * BASE + arr[i] + 1L;
            power[i + 1] = power[i] * BASE;
        }

        long hash1 = segmentHash(prefix, power, start1, suffixLength);
        long hash2 = segmentHash(prefix, power, start2, suffixLength);
        long hash3 = segmentHash(prefix, power, start3, suffixLength);
        if (hash1 != hash3 || hash2 != hash3) {
            return new int[]{-1, -1};
        }
        if (!sameBits(arr, start1, start3, suffixLength)
                || !sameBits(arr, start2, start3, suffixLength)) {
            return new int[]{-1, -1};
        }
        return new int[]{start1 + suffixLength - 1, start2 + suffixLength};
    }

    private long segmentHash(long[] prefix, long[] power, int start, int length) {
        return prefix[start + length] - prefix[start] * power[length];
    }

    private boolean sameBits(int[] arr, int left, int right, int length) {
        for (int offset = 0; offset < length; offset++) {
            if (arr[left + offset] != arr[right + offset]) {
                return false;
            }
        }
        return true;
    }
}
